CREATE OR REPLACE FUNCTION private.review_profile_change_request(p_request_id uuid, p_approve boolean, p_admin_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_request public.profile_change_requests%rowtype;
begin
  if not private.is_nexora_super_admin() then raise exception 'Only Super Admin can review profile requests' using errcode='42501'; end if;
  if p_approve is null then raise exception 'Approval decision is required'; end if;
  select * into v_request from public.profile_change_requests where id=p_request_id for update;
  if not found then raise exception 'Profile change request not found'; end if;
  if v_request.status <> 'pending' then raise exception 'This request has already been reviewed'; end if;
  if v_request.requested_full_name is null or length(trim(v_request.requested_full_name)) not between 1 and 150 then
    raise exception 'Invalid requested name';
  end if;
  if p_approve then
    update public.profiles set full_name=trim(v_request.requested_full_name),updated_at=now() where id=v_request.user_id;
    if not found then raise exception 'Profile not found'; end if;
    update public.profile_change_requests set status='approved',admin_note=nullif(trim(p_admin_note),''),reviewed_by=auth.uid(),reviewed_at=now() where id=p_request_id;
  else
    update public.profile_change_requests set status='rejected',admin_note=nullif(trim(p_admin_note),''),reviewed_by=auth.uid(),reviewed_at=now() where id=p_request_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.review_role_request(request_id uuid, decision text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_request public.role_requests%rowtype;
begin
  if not private.is_nexora_super_admin() then raise exception 'Only Super Admin can review requests' using errcode='42501'; end if;
  if decision not in ('approved','rejected') then raise exception 'Invalid decision'; end if;
  select * into target_request from public.role_requests where id=request_id and status='pending' for update;
  if not found then raise exception 'Pending request not found'; end if;
  update public.role_requests set status=decision where id=request_id;
  if decision='approved' then
    update public.profiles set role=target_request.requested_role,account_status='active',updated_at=now()
    where id=target_request.user_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_role text;
    v_full_name text;
    v_account_status text;
    v_provider text;
BEGIN
    v_provider := lower(coalesce(NEW.app_metadata ->> 'provider', ''));

    -- Social OAuth accounts always start as Buyer; never trust profile metadata for their role.
    IF v_provider IN ('google', 'facebook') THEN
        v_role := 'buyer';
    ELSE
        v_role := lower(trim(coalesce(NEW.raw_user_meta_data ->> 'role', 'buyer')));
        IF v_role = '' THEN
            v_role := 'buyer';
        END IF;
    END IF;

    IF v_role NOT IN ('buyer', 'seller', 'porter') THEN
        RAISE EXCEPTION 'Invalid registration role';
    END IF;

    v_full_name := nullif(trim(coalesce(
        NEW.raw_user_meta_data ->> 'full_name',
        NEW.raw_user_meta_data ->> 'name'
    )), '');

    IF v_full_name IS NOT NULL AND length(v_full_name) > 150 THEN
        RAISE EXCEPTION 'Full name is too long';
    END IF;

    IF v_role = 'porter' THEN
        v_account_status := 'pending';
    ELSE
        v_account_status := 'active';
    END IF;

    INSERT INTO public.profiles (id, full_name, role, account_status)
    VALUES (NEW.id, v_full_name, v_role, v_account_status)
    ON CONFLICT (id) DO NOTHING;

    RETURN NEW;
END;
$function$

